import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as m,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"局部搜索与最大割","description":"","frontmatter":{"title":"局部搜索与最大割","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/local-search-max-cut.md","filePath":"cs/local-search-max-cut.md","lastUpdated":1789023840000}'),p={name:"cs/local-search-max-cut.md"};function h(u,a,_,P,f,S){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="局部搜索与最大割" tabindex="-1">局部搜索与最大割 <a class="header-anchor" href="#局部搜索与最大割" aria-label="Permalink to &quot;局部搜索与最大割&quot;">​</a></h1><div class="epigraph"><p>翻转一个顶点若能增加割边则翻，局部最优至少一半边；Goemans–Williamson SDP 到 $0.878$。</p><footer>—— 据 Sahni and Gonzalez；Goemans and Williamson, Improved Approximation Algorithms for Maximum Cut, 1995；CLRS 第 35 章整理</footer></div><p>上一课<a href="/cs/knapsack-fptas">背包 FPTAS</a>是缩放 DP。最大割 NPC。缺口是局部搜索 2-近似（无向无权：割 \\(\\ge m/2\\)）以及 SDP 点名。不重写 LP 舍入框架。后课模拟退火把局部搜索加热。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>划分 \\(V=S\\cup T\\)，割为跨边。翻转 \\(v\\) 若内部边少于跨边则增益正。局部最优：每人的跨边 \\(\\ge\\) 内部，对边求和得 \\(2\\mathrm{ALG}\\ge m\\)，故 \\(\\mathrm{ALG}\\ge m/2\\ge\\mathrm{OPT}/2\\)。加权同样可局部。</p><p>GW：半定松弛 + 随机超平面，\\(0.878\\)。本课认结论，不写 SDP 求解。</p><p>缺口是翻转，不是 Karger（那是最小割）。</p><h3 id="局部最优不是全局" tabindex="-1">局部最优不是全局 <a class="header-anchor" href="#局部最优不是全局" aria-label="Permalink to &quot;局部最优不是全局&quot;">​</a></h3><p>可卡在 \\(1/2\\)。要更好用 SDP 或其它。不要无限翻转当多项式：每次增益至少 1（整数权）则多项式。</p><p><span class="marginnote">Goemans–Williamson 1995。局部搜索 2-近似是教材。后课模拟退火逃局部最优，无最坏比保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任意划分。循环扫描可改进的翻转直到停。随机初始化可多起点。</p>',12)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E5%88%92%E5%88%86%22%5D%20--%3E%20FLIP%5B%22%E6%9C%89%E5%A2%9E%E7%9B%8A%E5%88%99%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20FLIP%20--%3E%20LOC%5B%22%E5%B1%80%E9%83%A8%E6%9C%80%E4%BC%98%20%E2%89%A5%20m%2F2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>加权注意终止与精度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>握手：每点局部条件求和。每条割边计两次点贡献。与最大流最小割：最大割是另一目标，不能最小割算法直接翻。与 GW：几何舍入超平面。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(0.878\\) 与 Unique Games。不写最大有向割。后课默认：Max-Cut 局部搜索 \\(1/2\\)；SDP 更好。下一课模拟退火。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>翻转局部最优 \\(\\ge m/2\\)。</li><li>整数增益则多项式终止。</li><li>SDP \\(0.878\\) 点名。</li><li>出处：Goemans and Williamson, 1995；CLRS。</li></ul>',7))])}const E=l(p,[["render",h]]);export{A as __pageData,E as default};
